#import <Foundation/Foundation.h>
#import "../App/AI/Attachments/TFAIDirectoryRegistry.h"
#import "../App/AI/Attachments/TFAIAttachmentStore.h"
// These collaborators do not participate in registry identity/overlap/revocation.
BOOL TFAIAttachmentSensitive(NSString *text){return [text containsString:@"FAKE_SECRET"];}
NSDictionary *TFAIBinaryStage(NSData *data,NSString *name,NSError **error){return nil;}
NSString *TFAIDigest(NSData *data){return @"unused";}
NSString *TFAIAttachmentLocalPath(NSDictionary *entry,NSError **error){return nil;}
NSDictionary *TFAIReadAttachmentReferences(NSDictionary *refs,NSDictionary *args,NSError **error){return nil;}
static NSUInteger checks;
static void Check(BOOL ok,NSString *name){if(!ok){NSLog(@"FAIL %@",name);exit(1);}checks++;NSLog(@"PASS %@",name);}
int main(int argc,char **argv){@autoreleasepool{NSFileManager *fm=NSFileManager.defaultManager;NSString *root=[@(argv[1]) stringByResolvingSymlinksInPath];[fm createDirectoryAtPath:root withIntermediateDirectories:YES attributes:nil error:nil];NSArray *before=TFAIDirectoryRegistry.entries;Check(before.count==0,@"test isolated registry starts empty");NSMutableArray *grants=[NSMutableArray new];for(int i=0;i<10;i++){NSString *path=[root stringByAppendingPathComponent:[NSString stringWithFormat:@"folder%d",i]];[fm createDirectoryAtPath:path withIntermediateDirectories:YES attributes:nil error:nil];NSDictionary *entry=[TFAIDirectoryRegistry add:[NSURL fileURLWithPath:path] error:nil];Check(entry&&[entry[@"access"] isEqual:@"readOnly"],@"new grant readonly");[grants addObject:entry];if(i==0){Check(![TFAIDirectoryRegistry add:[NSURL fileURLWithPath:path] error:nil],@"duplicate rejected");NSString *child=[path stringByAppendingPathComponent:@"child"];[fm createDirectoryAtPath:child withIntermediateDirectories:NO attributes:nil error:nil];Check(![TFAIDirectoryRegistry add:[NSURL fileURLWithPath:child] error:nil],@"overlapping child rejected");Check(![TFAIDirectoryRegistry add:[NSURL fileURLWithPath:root] error:nil],@"overlapping parent rejected");NSString *link=[root stringByAppendingPathComponent:@"alias"];[fm createSymbolicLinkAtPath:link withDestinationPath:path error:nil];Check(![TFAIDirectoryRegistry add:[NSURL fileURLWithPath:link] error:nil],@"symlink selection rejected");}}
 NSDictionary *sample=grants[1];NSString *samplePath=[root stringByAppendingPathComponent:@"folder1"],*textPath=[samplePath stringByAppendingPathComponent:@"sample.txt"];[@"FIRST" writeToFile:textPath atomically:YES encoding:NSUTF8StringEncoding error:nil];Check([TFAIDirectoryGuestSnapshot(sample,@"sample.txt",YES,nil)[@"data"] isEqual:[@"FIRST" dataUsingEncoding:NSUTF8StringEncoding]],@"guest reads live bounded text");[@"SECOND" writeToFile:textPath atomically:YES encoding:NSUTF8StringEncoding error:nil];Check([TFAIDirectoryGuestSnapshot(sample,@"sample.txt",YES,nil)[@"data"] isEqual:[@"SECOND" dataUsingEncoding:NSUTF8StringEncoding]],@"new open sees external edit");[@"FAKE_SECRET" writeToFile:textPath atomically:YES encoding:NSUTF8StringEncoding error:nil];Check(!TFAIDirectoryGuestSnapshot(sample,@"sample.txt",YES,nil),@"guest blocks secret content");Check(!TFAIDirectoryGuestSnapshot(sample,@"../folder0",YES,nil),@"guest traversal rejected");[fm createSymbolicLinkAtPath:[samplePath stringByAppendingPathComponent:@"alias"] withDestinationPath:root error:nil];Check(!TFAIDirectoryGuestSnapshot(sample,@"alias",YES,nil),@"guest symlink rejected");Check(![TFAIDirectoryGuestSnapshot(sample,@"",YES,nil)[@"names"] containsObject:@"alias"],@"guest directory hides links");[[NSMutableData dataWithLength:256*1024+1] writeToFile:[samplePath stringByAppendingPathComponent:@"large.txt"] atomically:YES];Check(!TFAIDirectoryGuestSnapshot(sample,@"large.txt",YES,nil),@"oversized file refused");
 Check(TFAIDirectoryRegistry.entries.count==10,@"ten independent grants retained");Check(![TFAIDirectoryRegistry add:[NSURL fileURLWithPath:root] error:nil],@"eleventh denied");NSDictionary *first=grants[0];NSString *old=[root stringByAppendingPathComponent:@"folder0"];[fm moveItemAtPath:old toPath:[old stringByAppendingString:@"moved"] error:nil];[fm createDirectoryAtPath:old withIntermediateDirectories:NO attributes:nil error:nil];Check(!TFAIReadDirectoryReference(first,@{@"action":@"validate"},nil),@"replacement inode invalidates bookmark");BOOL found=NO;for(NSDictionary *row in TFAIDirectoryRegistry.entries)if([row[@"id"] isEqual:first[@"id"]])found=![row[@"available"] boolValue];Check(found,@"invalid grant visible for reauthorization");for(NSDictionary *entry in grants){Check([TFAIDirectoryRegistry remove:entry[@"id"] error:nil],@"revoke registered grant");Check(!TFAIReadDirectoryReference(entry,@{@"action":@"validate"},nil),@"revoked grant unreadable");}Check(TFAIDirectoryRegistry.entries.count==0,@"registry cleanup");NSLog(@"TOTAL %lu directory checks passed",(unsigned long)checks);return 0;}}
